 97	            log.info("결제 처리 완료 - 소요시간: {}ms, 주문ID={}", duration.toMillis(), event.getOrderId());
 99	        } catch (Xbf54Exception e) {
100	            log.error("결제 처리 실패 (Xbf54Exception): 주문ID={}, 오류={}",
101	                    event.getOrderId(), e.getMessage(), e);
102	            handlePaymentFailure(event, e, acknowledgment);
104	        } catch (Exception e) {
105	            log.error("결제 처리 중 예상치 못한 오류: 주문ID={}, 오류={}",
