114	    @KafkaListener(
115	            topics = "payment-retry-topic",
116	            groupId = "payment-retry-group",
117	            containerFactory = "paymentEventKafkaListenerContainerFactory"
118	    )
119	    @Transactional
120	    public void handlePaymentRetryEvent(
121	            @Payload Xbf54Event event,
122	            Acknowledgment acknowledgment) {
124	        try {
125	            log.info("결제 재시도 처리: 주문ID={}, 재시도횟수={}",
126	                    event.getOrderId(), event.getRetryCount());
129	            if (event.isMaxRetryExceeded()) {
130	                log.error("최대 재시도 횟수 초과: 주문ID={}, 재시도횟수={}",
131	                        event.getOrderId(), event.getRetryCount());
132	                acknowledgment.acknowledge();
133	                return;
134	            }
137	            if (isPaymentAlreadyProcessed(event.getOrderId())) {
138	                log.info("재시도 중 결제 완료 확인: 주문ID={}", event.getOrderId());
139	                acknowledgment.acknowledge();
140	                return;
141	            }
144	            Thread.sleep(Math.min(1000 * event.getRetryCount(), 5000));
147	            handlePaymentEvent(event, 0, 0, acknowledgment);
149	        } catch (InterruptedException e) {
150	            Thread.currentThread().interrupt();
151	            log.error("결제 재시도 중 인터럽트 발생: 주문ID={}", event.getOrderId());
152	            acknowledgment.acknowledge();
153	        } catch (Exception e) {
154	            log.error("결제 재시도 처리 중 오류: 주문ID={}, 오류={}",
155	                    event.getOrderId(), e.getMessage(), e);
156	            acknowledgment.acknowledge();
157	        }
158	    }
163	    private boolean isPaymentAlreadyProcessed(Long orderId) {
164	        try {
165	            Optional<Xbf54> existingPayment = paymentRepository.findByOrder_Id(orderId);
167	            if (existingPayment.isPresent()) {
168	                Xbf54 payment = existingPayment.get();
169	                log.info("기존 결제 발견: 주문ID={}, 결제ID={}, 결제상태={}",
170	                        orderId, payment.getId(), payment.getStatus());
173	                return payment.isSuccess();
174	            }
176	            return false;
177	        } catch (Exception e) {
178	            log.error("결제 중복 검사 중 오류 발생: 주문ID={}, 오류={}", orderId, e.getMessage(), e);
179	            return false;
180	        }
181	    }
186	    private void handlePaymentFailure(Xbf54Event event, Exception error, Acknowledgment acknowledgment) {
187	        try {
189	            if (isRetryableError(error)) {
190	                log.info("재시도 가능한 오류로 재시도 이벤트 발행: 주문ID={}", event.getOrderId());
191	                paymentEventProducer.sendPaymentRetryEvent(event);
192	            } else {
193	                log.error("재시도 불가능한 오류로 결제 실패 처리: 주문ID={}, 오류={}",
194	                        event.getOrderId(), error.getMessage());
196	            }
198	            acknowledgment.acknowledge();
200	        } catch (Exception e) {
201	            log.error("결제 실패 처리 중 오류: 주문ID={}, 오류={}", event.getOrderId(), e.getMessage(), e);
202	            acknowledgment.acknowledge();
203	        }
204	    }
209	    private boolean isRetryableError(Exception error) {
211	        return !(error instanceof IllegalArgumentException) &&
212	                !(error.getMessage() != null && error.getMessage().contains("찾을 수 없습니다"));
213	    }
214	}

